#!/usr/bin/env python3
"""A fake ``codex`` CLI for autonomous-worker tests.

Stands in for the real Codex CLI in ``python3 -m defsec_reasoner
codex-worker`` tests. It is executed with exactly the argv and scrubbed
environment the worker gives the real binary, reads the prompt from stdin,
parses the ``-c mcp_servers.defsec.*`` overrides to find the ``mcp-adapter``
binary it must launch, and then:

* verifies the worker's hygiene contract from the inside:
  - no ``DEFSEC_*`` variables are present in its environment,
  - the run token (read from ``--token-file``) is nowhere in its own
    ``/proc/self/cmdline``,
  - the token is not in the adapter's ``/proc/<pid>/cmdline`` either,
  - the token file is mode 0600 inside a 0700 directory;
* speaks real MCP JSON-RPC to the adapter (initialize, tools/list and
  behavior-driven tools/call), so the end-to-end path runs against the real
  ``mcp-adapter`` and ``control-d``;
* emits Codex-style JSONL events (the ``ThreadEvent`` schema of codex-cli
  0.172.0) on stdout, one JSON object per line, flushed per event.

The behavior is selected with the ``-m/--model`` argument the worker passes
through: ``happy`` (default), ``timeout``, ``crash``, ``auth-error``,
``flood``, ``no-events``. A failed hygiene check makes every behavior emit a
loud ``error`` event and exit non-zero, so the happy-path run only completes
when the worker kept its promises.

This script must stay runnable with a bare stdlib-only interpreter and no
repository imports: it runs inside the scrubbed child environment.
"""

from __future__ import annotations

import json
import os
import subprocess
import sys
import time
import uuid

MCP_SERVER = "defsec"
PROTOCOL_VERSION = "2025-03-26"
USAGE = {
    "input_tokens": 24763,
    "cached_input_tokens": 24448,
    "cache_write_input_tokens": 0,
    "output_tokens": 122,
    "reasoning_output_tokens": 0,
}


def log_event(payload: dict) -> None:
    sys.stdout.write(json.dumps(payload, separators=(",", ":")) + "\n")
    sys.stdout.flush()


def fail_hard(message: str) -> None:
    log_event({"type": "error", "message": f"fake-codex: {message}"})
    sys.stderr.write(f"fake-codex: {message}\n")
    sys.stderr.flush()
    sys.exit(3)


# ------------------------------------------------------------------- argv/env


def parse_config_overrides(argv: list[str]) -> dict[str, object]:
    """Collect ``-c key=value`` overrides, parsing the TOML-ish values."""
    overrides: dict[str, object] = {}
    index = 0
    while index < len(argv):
        if argv[index] == "-c" and index + 1 < len(argv):
            pair = argv[index + 1]
            key, sep, value = pair.partition("=")
            if sep:
                value = value.strip()
                try:
                    if value.startswith("[") or value.startswith('"'):
                        parsed = json.loads(value)
                    else:
                        parsed = value
                except json.JSONDecodeError:
                    parsed = value
                overrides[key.strip()] = parsed
            index += 2
            continue
        if argv[index] == "-m" and index + 1 < len(argv):
            overrides["__model__"] = argv[index + 1]
            index += 2
            continue
        index += 1
    return overrides


def cmdline_of(pid: int) -> str:
    try:
        with open(f"/proc/{pid}/cmdline", "rb") as handle:
            return handle.read().decode("utf-8", errors="replace").replace("\0", " ")
    except OSError:
        return ""


def read_prompt() -> str:
    return sys.stdin.read()


def parse_run_header(prompt: str) -> dict:
    """Extract the trusted RUN CONTEXT header JSON from the prompt."""
    lines = prompt.splitlines()
    for index, line in enumerate(lines):
        if not line.startswith("RUN CONTEXT (trusted, generated by"):
            continue
        for follow in lines[index + 1 : index + 5]:
            text = follow.strip()
            if not text.startswith("{"):
                continue
            try:
                header, _ = json.JSONDecoder().raw_decode(text)
            except json.JSONDecodeError:
                continue
            if isinstance(header, dict):
                return header
    return {}


# ------------------------------------------------------------------- MCP side


class McpClient:
    """Minimal newline-delimited JSON-RPC 2.0 client for the adapter."""

    def __init__(self, command: str, args: list[str]) -> None:
        self.process = subprocess.Popen(
            [command, *args],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=dict(os.environ),
        )
        self._next_id = 1
        self.calls: list[dict] = []

    def request(self, method: str, params: dict | None = None) -> dict:
        message: dict = {"jsonrpc": "2.0", "id": self._next_id, "method": method}
        self._next_id += 1
        if params is not None:
            message["params"] = params
        return self._roundtrip(message)

    def notify(self, method: str) -> None:
        payload = json.dumps({"jsonrpc": "2.0", "method": method}) + "\n"
        assert self.process.stdin is not None
        self.process.stdin.write(payload.encode())
        self.process.stdin.flush()

    def tool_call(self, name: str, arguments: dict) -> dict:
        reply = self.request(
            "tools/call", {"name": name, "arguments": arguments}
        )
        if "error" in reply:
            return {"isError": True, "content": [{"type": "text", "text": json.dumps(reply["error"])}]}
        self.calls.append({"name": name, "arguments": arguments, "result": reply.get("result")})
        return reply.get("result") or {}

    def close(self) -> None:
        try:
            if self.process.stdin is not None:
                self.process.stdin.close()
            self.process.wait(timeout=5)
        except Exception:
            self.process.kill()

    def _roundtrip(self, message: dict) -> dict:
        assert self.process.stdin is not None and self.process.stdout is not None
        self.process.stdin.write(json.dumps(message).encode() + b"\n")
        self.process.stdin.flush()
        line = self.process.stdout.readline()
        if not line:
            fail_hard("the MCP adapter closed its stdout before replying")
        try:
            return json.loads(line.decode())
        except json.JSONDecodeError:
            fail_hard("the MCP adapter produced a non-JSON reply")


def mcp_result_content(result: dict) -> list:
    return result.get("content") or []


def mcp_payload(result: dict) -> dict | None:
    for block in mcp_result_content(result):
        text = block.get("text") if isinstance(block, dict) else None
        if not isinstance(text, str):
            continue
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError:
            continue
        if isinstance(parsed, dict):
            return parsed
    return None


# ------------------------------------------------------------------ behaviors


def emit_item(phase: str, item: dict) -> None:
    log_event({"type": phase, "item": {"id": f"item_{emit_item.counter}", **item}})
    emit_item.counter += 1


emit_item.counter = 1


def mcp_tool_events(client: McpClient, name: str, arguments: dict) -> dict:
    emit_item(
        "item.started",
        {"type": "mcp_tool_call", "server": MCP_SERVER, "tool": name, "arguments": arguments,
         "status": "in_progress"},
    )
    result = client.tool_call(name, arguments)
    failed = bool(result.get("isError"))
    item: dict = {
        "type": "mcp_tool_call",
        "server": MCP_SERVER,
        "tool": name,
        "arguments": arguments,
        "status": "failed" if failed else "completed",
    }
    if failed:
        item["error"] = {"message": json.dumps(result.get("content"))[:400]}
    else:
        item["result"] = {"content": mcp_result_content(result)}
    emit_item("item.completed", item)
    return result


def rfc3339_in_days(days: int) -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + days * 86400))


def run_happy(client: McpClient, header: dict, checks: dict) -> None:
    host_id = str(header.get("host_id") or "edge-01")
    incident_id = str(header.get("incident_id") or "inc-1")

    query = mcp_tool_events(
        client,
        "query_observations",
        {"host_id": host_id, "watch_id": "w-sockets", "limit": 50},
    )
    payload = mcp_payload(query) or {}
    observations = payload.get("observations") or []
    evidence = sorted(
        int(row["observation_id"]) for row in observations
        if isinstance(row, dict) and "observation_id" in row
    )
    if not evidence:
        fail_hard("query_observations returned no evidence ids")

    mcp_tool_events(
        client,
        "record_hypothesis_or_finding",
        {
            "incident_id": incident_id,
            "kind": "verified_finding",
            "severity": "medium",
            "summary": "fake-codex recorded an evidence-bound finding for the trigger diff",
            "uncertainty": "deterministic fake run; no real model inference",
            "evidence_observation_ids": evidence,
            "escalation_requested": False,
        },
    )
    mcp_tool_events(
        client,
        "propose_expectation_rule",
        {
            "idempotency_key": f"fake-codex-{uuid.uuid4().hex[:8]}",
            "rule": {
                "scope": {"host_id": host_id, "collector": "sockets.listening", "watch_id": "w-sockets"},
                "matches": [
                    {"op": "eq", "field": "systemd_unit", "value": "sshd.service"},
                    {"op": "eq", "field": "local_port", "value": 22},
                ],
                "effect": "allow_optional",
                "rationale": "sshd.service legitimately re-listens on its pinned port after restarts",
                "expires_at": rfc3339_in_days(3),
            },
        },
    )
    emit_item("item.completed", {"type": "agent_message", "text": "Evidence reviewed; recording the conclusion."})
    report = dict(checks)
    report["mcp_calls"] = len(client.calls)
    report["evidence_ids"] = evidence
    emit_item(
        "item.completed",
        {"type": "agent_message", "text": "fake-codex-report: " + json.dumps(report)},
    )
    log_event({"type": "turn.completed", "usage": USAGE})


def run_timeout(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    grandchild = subprocess.Popen(["sleep", "300"], stdout=subprocess.DEVNULL)
    log_event({"type": "thread.started", "thread_id": f"{os.getpid()}:{grandchild.pid}"})
    log_event({"type": "turn.started"})
    log_event(
        {"type": "item.started", "item": {"id": "item_1", "type": "agent_message",
                                          "text": "thinking slowly…", "status": "in_progress"}}
    )
    time.sleep(300)


def run_crash(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    log_event({"type": "thread.started", "thread_id": str(os.getpid())})
    log_event({"type": "turn.started"})
    sys.stdout.flush()
    os._exit(137)


def run_auth_error(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    log_event({"type": "thread.started", "thread_id": str(os.getpid())})
    message = "You are not logged in. Run `codex login` to sign in with your ChatGPT account."
    log_event({"type": "error", "message": message})
    sys.stderr.write(message + "\n")
    sys.stderr.flush()
    sys.exit(1)


def run_flood(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    log_event({"type": "thread.started", "thread_id": str(os.getpid())})
    log_event({"type": "turn.started"})
    filler = "x" * 40
    for index in range(3000):
        log_event(
            {"type": "item.completed", "item": {"id": f"item_{index}", "type": "agent_message",
                                                 "text": f"flood {index} {filler}"}}
        )


def run_no_events(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    return


def run_incomplete(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    log_event({"type": "turn.started"})
    log_event({"type": "unknown_event"})
    print("not JSON", flush=True)
    # The final bytes resemble a valid event but belong to the oversized line.
    print("x" * (256 * 1024 + 1) + '{"type":"turn.completed"}', flush=True)
    log_event({"type": "turn.completed", "usage": "invalid"})
    emit_item("item.completed", {"type": "agent_message", "text": "incomplete turn"})


def run_orphan(_client: McpClient | None, _header: dict, _checks: dict) -> None:
    code = "import signal, time; signal.signal(signal.SIGTERM, signal.SIG_IGN); print('ready', flush=True); time.sleep(20)"
    child = subprocess.Popen([sys.executable, "-c", code], stdin=subprocess.DEVNULL,
                             stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    with child.stdout:
        child.stdout.readline()
    log_event({"type": "thread.started", "thread_id": str(child.pid)})
    log_event({"type": "turn.started"})
    log_event({"type": "turn.completed", "usage": USAGE})


BEHAVIORS = {
    "happy": run_happy,
    "timeout": run_timeout,
    "crash": run_crash,
    "auth-error": run_auth_error,
    "flood": run_flood,
    "no-events": run_no_events,
    "incomplete": run_incomplete,
    "orphan": run_orphan,
}


def main() -> int:
    overrides = parse_config_overrides(sys.argv[1:])
    model = str(overrides.get("__model__") or "happy")
    if model == "stalled-input":
        time.sleep(4)
        return 0
    prompt = read_prompt()
    behavior = BEHAVIORS.get(model)
    if behavior is None:
        fail_hard(f"unknown fake behavior {model!r}")

    adapter_command = overrides.get(f"mcp_servers.{MCP_SERVER}.command")
    adapter_args = overrides.get(f"mcp_servers.{MCP_SERVER}.args")
    if not isinstance(adapter_command, str) or not isinstance(adapter_args, list):
        fail_hard("mcp_servers.defsec command/args overrides are missing")

    token_file = None
    for index, value in enumerate(adapter_args):
        if value == "--token-file" and index + 1 < len(adapter_args):
            token_file = str(adapter_args[index + 1])
    if token_file is None:
        fail_hard("adapter args carry no --token-file")
    with open(token_file, "r", encoding="utf-8") as handle:
        run_token = handle.read().strip()

    # Hygiene checks judged from inside the child process.
    checks: dict = {
        "behavior": model,
        "cwd": os.getcwd(),
        "token_file": token_file,
        "token_mode": oct(os.stat(token_file).st_mode & 0o777),
        "token_dir_mode": oct(os.stat(os.path.dirname(token_file)).st_mode & 0o777),
        "env_defsec_vars": sorted(k for k in os.environ if k.startswith("DEFSEC_")),
        "env_keys": sorted(os.environ),
        "argv_token": run_token in cmdline_of(os.getpid()),
        "prompt_bytes": len(prompt.encode("utf-8")),
    }
    if checks["env_defsec_vars"]:
        fail_hard(f"DEFSEC_* variables leaked into the codex environment: {checks['env_defsec_vars']}")
    if checks["argv_token"]:
        fail_hard("the run token appeared on the codex command line")
    if checks["token_mode"] != "0o600":
        fail_hard(f"token file mode is {checks['token_mode']}, expected 0600")
    if checks["token_dir_mode"] != "0o700":
        fail_hard(f"token dir mode is {checks['token_dir_mode']}, expected 0700")

    header = parse_run_header(prompt)
    if behavior is run_happy and not header.get("incident_id"):
        fail_hard("the prompt carries no run context header")

    client: McpClient | None = None
    if behavior is run_happy:
        client = McpClient(adapter_command, [str(a) for a in adapter_args])
        client.request(
            "initialize",
            {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": "fake-codex", "version": "0.1.0"},
            },
        )
        client.notify("notifications/initialized")
        listed = client.request("tools/list", {})
        tools = [t.get("name") for t in (listed.get("result") or {}).get("tools") or []]
        checks["tools_seen"] = sorted(name for name in tools if isinstance(name, str))
        checks["adapter_argv_token"] = run_token in cmdline_of(client.process.pid)
        if checks["adapter_argv_token"]:
            fail_hard("the run token appeared on the adapter command line")
        for required in ("query_observations", "record_hypothesis_or_finding", "propose_expectation_rule"):
            if required not in tools:
                fail_hard(f"the adapter tool list is missing {required}")

    try:
        if behavior is run_happy:
            thread_id = sys.argv[sys.argv.index("resume") + 1] if "resume" in sys.argv else str(uuid.uuid4())
            log_event({"type": "thread.started", "thread_id": thread_id})
            log_event({"type": "turn.started"})
            behavior(client, header, checks)
        else:
            behavior(client, header, checks)
    finally:
        if client is not None:
            client.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
